document.addEventListener("DOMContentLoaded",()=>{new StickyHeader("header",{offset:150,threshold:6})}),document.addEventListener("DOMContentLoaded",()=>{var e=document.createElement("div");e.classList.add("scroll-to-top"),e.innerHTML='<a href="#"><span class="fa fa-regular fa-chevron-up"></span></a>',document.body.appendChild(e),window.addEventListener("scroll",()=>{window.scrollY>100?e.style.display="flex":e.style.display="none"}),e.addEventListener("click",e=>{e.preventDefault(),window.scrollTo({top:0,behavior:"smooth"})})}),document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".handorgel__header__button");for(const n of e)n.insertAdjacentHTML("afterbegin",'<i class="icon-expand fa-light fa-plus-large"></i><i class="icon-collapse fa-light fa-dash"></i>')}),document.addEventListener("csn:initialized",e=>{const n=e.detail.nav_element.querySelectorAll(".toggle-submenu.csn--dropdown-toggle");for(const e of n)e.insertAdjacentHTML("afterbegin",'<i class="fa-regular fa-angle-right"></i>')});